/* Final birthday entry. Review tools and save data are isolated by ?preview=1. */
const birthdayReview=new URLSearchParams(location.search).get('preview')==='1';
function birthdayRestart(){if(!campaign.started&&stage===0){reset();return}if(document.querySelector('#birthdayRestartDialog'))return;const wasLetter=!!document.querySelector('.birthday-finale');cpStop();const d=document.createElement('dialog');d.id='birthdayRestartDialog';d.className='birthday-confirm';d.innerHTML='<div class="eyebrow">A LITTLE WALK</div><h2>要重新走一遍吗？</h2><p>重新开始会清空'+(birthdayReview?'电脑测试':'这次旅程')+'的关卡、合照和小屋布置。<br>如果只是想休息一下，直接关掉页面，回来还能接着走。</p><div><button id="birthdayKeepPlaying" class="primary">继续现在的旅程</button><button id="birthdayConfirmRestart" class="text">确认重新开始</button></div>';document.body.append(d);let confirmed=false;d.onclose=()=>{d.remove();if(!confirmed){if(wasLetter)albumGift();else render()}};d.querySelector('#birthdayKeepPlaying').onclick=()=>d.close();d.querySelector('#birthdayConfirmRestart').onclick=()=>{confirmed=true;d.close();reset()};d.showModal();d.querySelector('#birthdayKeepPlaying').focus()}
function birthdayCloseTransient(){roomDrag=null;document.querySelector('#roomDragGhost')?.remove();document.querySelectorAll('.drop-ready').forEach(el=>el.classList.remove('drop-ready'))}
function birthdayReaction(){const pair=document.querySelector('.album-room-pair');if(!pair)return;pair.setAttribute('role','button');pair.setAttribute('tabindex','0');pair.setAttribute('aria-label','靠近一点，和我一起坐一会儿');const react=()=>{if(pair.querySelector('.birthday-heart'))return;const heart=document.createElement('span');heart.className='birthday-heart';heart.textContent='♡';heart.setAttribute('aria-hidden','true');pair.append(heart);document.querySelector('#roomPlacementStatus').textContent='来，靠近一点。以后这面照片墙，我们还要一起慢慢填满。';chime();setTimeout(()=>heart.remove(),motionOff()?500:1500)};pair.onclick=react;pair.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();react()}}}
function birthdayPolish(){document.querySelector('#skip').hidden=true;document.querySelector('#restart').onclick=birthdayRestart;document.querySelector('#brand').onclick=e=>{e.preventDefault();if(campaign.started)cpMap();else render()};document.body.classList.toggle('birthday-review',birthdayReview);if(campaign.started){const progress=document.querySelector('.journey');if(progress){progress.setAttribute('aria-label','整段旅程进度');progress.innerHTML=CP_NODES.map(([id,label],i)=>`<span class="${campaign.done.includes(id)?'complete':campaign.route===id?'current':''}"><i>${campaign.done.includes(id)?'✓':i+1}</i>${label.replace('亮着灯的','').replace('琉璃阁的回忆','琉璃回忆').replace('水车与风的路','水与风')}</span>`).join('')}}birthdayReaction();if(stage===0&&!campaign.active&&!memory.active){chapter.textContent=birthdayReview?'电脑测试 · 独立进度':'一起走一小段路 · 生日篇';const label=document.querySelector('.album-intro .eyebrow');if(label)label.textContent=birthdayReview?'DESKTOP REVIEW · 电脑测试':'A LITTLE WALK · JUST FOR YOU'}const rotate=document.querySelector('#birthdayOrientation');if(rotate)rotate.hidden=innerWidth>=innerHeight}
const birthdayOldRender=render;render=function(){birthdayCloseTransient();birthdayOldRender();birthdayPolish()};
const orientation=document.createElement('div');orientation.id='birthdayOrientation';orientation.innerHTML='<span>↻</span>把平板横过来，和身边的人一起看会更舒服。';orientation.setAttribute('role','note');document.body.append(orientation);
window.addEventListener('resize',()=>orientation.hidden=innerWidth>=innerHeight);
window.addEventListener('blur',birthdayCloseTransient);document.addEventListener('visibilitychange',()=>{if(document.hidden)birthdayCloseTransient()});
render();
